-- Historical recovery only. Do not apply to an existing production database.
-- Original recorded version: 20260815053503
on conflict(product_key) do update set product_name=excluded.product_name,product_type=excluded.product_type,billing_period=excluded.billing_period,recommended_price_minor=excluded.recommended_price_minor,currency=excluded.currency,audience_stage_keys=excluded.audience_stage_keys,description=excluded.description,features=excluded.features,active=excluded.active,display_order=excluded.display_order,updated_at=now();

with grade_map as (
  select 'school_1_6'::text stage_key, generate_series(1,6)::smallint grade_level
  union all select 'school_7_8', generate_series(7,8)::smallint
  union all select 'school_9_10', generate_series(9,10)::smallint
  union all select 'school_11_12', generate_series(11,12)::smallint
), src as (
  select distinct n.stage_key,n.track_key,n.subject_key,n.subject_title,n.optional,min(n.display_order) over(partition by n.stage_key,n.track_key,n.subject_key) display_order,n.source_name,n.source_url
  from public.mela_national_subject_catalog n
  where n.active
)
select 'g'||g.grade_level||'_'||s.track_key||'_'||s.subject_key,
       s.stage_key,g.grade_level,s.track_key,s.subject_key,s.subject_title,
       'Grade '||g.grade_level||' '||s.subject_title||case when s.stage_key='school_11_12' then ' — '||initcap(replace(s.track_key,'_',' ')) else '' end,
       'Mela supplemental learning program for Grade '||g.grade_level||' '||s.subject_title||'. Detailed unit-to-official-syllabus mapping requires educator review before Mela represents any lesson as officially aligned.',
       'school_subject','official_subject_listing_confirmed_content_pending_mapping',s.source_name,s.source_url,s.optional,true,(g.grade_level*1000)+s.display_order,
       jsonb_build_object('source_scope','official subject listing','content_scope','Mela supplemental until detailed syllabus mapping','track',s.track_key)
from src s join grade_map g on g.stage_key=s.stage_key
on conflict(program_key) do update set title=excluded.title,description=excluded.description,official_alignment_status=excluded.official_alignment_status,source_name=excluded.source_name,source_url=excluded.source_url,optional=excluded.optional,active=true,display_order=excluded.display_order,metadata=excluded.metadata,updated_at=now();

on conflict(program_key) do update set title=excluded.title,description=excluded.description,official_alignment_status=excluded.official_alignment_status,source_name=excluded.source_name,source_url=excluded.source_url,active=true,display_order=excluded.display_order,metadata=excluded.metadata,updated_at=now();
;
